#include <bits/stdc++.h>
using namespace std;const int N=262144,P=998244353,G=3;int f0[N],g0[N],q0[N],r0[N],a[N],b[N],v[N];int q(int a,int n=P-2){int r=1;for(;n;n>>=1,a=1LL*a*a%P)if(n&1)r=1LL*r*a%P;return r;}void t(int*a,int n,int z){for(int i=0;i<n;i++)if(i<v[i])swap(a[i],a[v[i]]);for(int l=2;l<=n;l<<=1){int w=q(G,(P-1)/l);if(z<0)w=q(w);for(int i=0;i<n;i+=l)for(int j=0,x=1;j<l/2;j++,x=1LL*x*w%P){int u=a[i+j],y=1LL*x*a[i+j+l/2]%P;a[i+j]=(u+y)%P;a[i+j+l/2]=(u-y+P)%P;}}if(z<0){int x=q(n);for(int i=0;i<n;i++)a[i]=1LL*a[i]*x%P;}}void h(int*s,int*d,int n){d[0]=q(s[0]);for(int k=1;k<n;k<<=1){int l=k<<1,L=k<<2,z=__builtin_ctz(L);for(int i=0;i<L;i++)a[i]=i<l&&i<n?s[i]:0,b[i]=i<k?d[i]:0;for(int i=1;i<L;i++)v[i]=(v[i>>1]>>1)|((i&1)<<(z-1));t(a,L,1);t(b,L,1);for(int i=0;i<L;i++)b[i]=1LL*b[i]*(2-1LL*a[i]*b[i]%P+P)%P;t(b,L,-1);for(int i=k;i<l&&i<n;i++)d[i]=b[i];}}int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m;cin>>n>>m;for(int i=0;i<=n;i++)cin>>f0[i];for(int i=0;i<=m;i++)cin>>g0[i];int k=n-m+1;for(int i=0;i<k;i++)r0[i]=i<=m?g0[m-i]:0;h(r0,q0,k);int l=1,z=0;while(l<2*k-1)l<<=1;while((1<<z)<l)z++;for(int i=0;i<l;i++)a[i]=i<k?f0[n-i]:0,b[i]=i<k?q0[i]:0;for(int i=1;i<l;i++)v[i]=(v[i>>1]>>1)|((i&1)<<(z-1));t(a,l,1);t(b,l,1);for(int i=0;i<l;i++)a[i]=1LL*a[i]*b[i]%P;t(a,l,-1);for(int i=0;i<k;i++)q0[i]=a[k-1-i];l=1;z=0;while(l<=n)l<<=1;while((1<<z)<l)z++;for(int i=0;i<l;i++)a[i]=i<k?q0[i]:0,b[i]=i<=m?g0[i]:0;for(int i=1;i<l;i++)v[i]=(v[i>>1]>>1)|((i&1)<<(z-1));t(a,l,1);t(b,l,1);for(int i=0;i<l;i++)a[i]=1LL*a[i]*b[i]%P;t(a,l,-1);for(int i=0;i<m;i++)r0[i]=(f0[i]-a[i]+P)%P;for(int i=0;i<k;i++)cout<<q0[i]<<' ';cout<<'\n';for(int i=0;i<m;i++)cout<<r0[i]<<' ';cout<<'\n';}
